// Builds code.js (the file Figma runs) from src/: icons + image assets + builder + screens.
import { readFileSync, writeFileSync } from "node:fs";
const here = new URL(".", import.meta.url);
const read = (p) => readFileSync(new URL(p, here), "utf8");
const icons = JSON.parse(read("src/icons.json"));
const assets = JSON.parse(read("src/assets.json"));
const out = [
  "// GENERATED by build.mjs from src/ — edit the files in src/, then run: node build.mjs",
  `const ICONS = ${JSON.stringify(icons)};`,
  `const ASSETS = ${JSON.stringify(assets)};`,
  read("src/builder.js"), read("src/screens1.js"), read("src/screens2.js"), read("src/screens3.js"), read("src/main.js"),
].join("\n");
writeFileSync(new URL("code.js", here), out);
console.log(`code.js written (${Math.round(out.length / 1024)} KB)`);
